import math
fn putd(mut o &u8,p int,x f64){bits:=u64(math.bits_from_f64(x));for k in 0..8{unsafe{o[p+k]=u8(bits&255)};bits>>=8}}
@[export:'fuzzy_set_operations']
pub fn fuzzy_set_operations(v &i64,n usize,o &u8,cap usize)i64{if isnil(v)||n<8{return -1};op:=unsafe{v[0]};m:=unsafe{v[1]};if op<0||op>8||m<1||m>8||n!=usize(5+3*m){return -1};for i in 5..int(n){x:=unsafe{v[i]};if x<0||x>1000{return -1}};l:=unsafe{v[2]};p:=unsafe{v[3]};r:=unsafe{v[4]};if op==0{if l<0||p<l||r<p||r>1000{return -1};for i in 0..int(m){if unsafe{v[5+int(m)+i]!=0||v[5+2*int(m)+i]!=0}{return -1}}}else{if l!=0||p!=0||r!=0{return -1};for i in 0..int(m){if unsafe{v[5+i]!=0}{return -1}}};if isnil(o)||cap<int(m)*8{return -2};for i in 0..int(m){mut z:=0.0;if op==0{x:=f64(unsafe{v[5+i]})/1000.;a:=f64(l)/1000.;b:=f64(p)/1000.;c:=f64(r)/1000.;u:=if b>a{(x-a)/(b-a)}else if x<b{0.0}else{1.0};w:=if c>b{(c-x)/(c-b)}else if x>c{0.0}else{1.0};z=math.max(0.0,math.min(1.0,math.min(u,w)))}else{a:=f64(unsafe{v[5+int(m)+i]})/1000.;b:=f64(unsafe{v[5+2*int(m)+i]})/1000.;match op{1{z=math.max(a,b)}2{z=math.min(a,b)}3{z=1-a}4{z=math.min(a,1-b)}5{z=a+b-a*b}6{z=a*b}7{z=math.min(1,a+b)}else{z=math.max(0,a+b-1)}}};putd(mut o,i*8,z)};m*8}
